context(context: CheckerContext, reporter: DiagnosticReporter)
override fun checkPsi(
    element: FirStatement,
    source: KtPsiSourceElement,
    psi: PsiElement,
) {
    var current = source.psi
    var parent = current.parent

    while (parent is KtBinaryExpression) {
        if (parent.left != current) {
            return
        }

        current = parent
        parent = parent.parent
    }

    if (isStatementContainer(parent)) {
        reporter.reportOn(source, FirErrors.ANNOTATIONS_ON_BLOCK_LEVEL_EXPRESSION_ON_THE_SAME_LINE)
    }
}

context(context: CheckerContext, reporter: DiagnosticReporter)
override fun checkPsi(
    element: FirWhenExpression,
    source: KtPsiSourceElement,
    psi: PsiElement,
) {
    val subjectType = element.subjectVariable?.initializer?.resolvedType ?: element.subjectVariable?.returnTypeRef?.coneType ?: return
    val booleanSubject = subjectType.isBooleanOrNullableBoolean
    val whenExpression = psi as KtWhenExpression
    if (whenExpression.subjectExpression == null && whenExpression.subjectVariable == null) return
    for (entry in whenExpression.entries) {
        for (condition in entry.conditions) {
            checkCondition(booleanSubject, condition)
        }
    }
}

context(context: CheckerContext, reporter: DiagnosticReporter)
private fun checkCondition(
    booleanSubject: Boolean,
    condition: KtWhenCondition,
) {
    when (condition) {
        is KtWhenConditionWithExpression -> checkConditionExpression(booleanSubject, condition.expression)
        is KtWhenConditionInRange -> checkConditionExpression(booleanSubject, condition.rangeExpression)
    }
}

context(context: CheckerContext, reporter: DiagnosticReporter)
private fun checkConditionExpression(
    booleanSubject: Boolean,
    rawExpression: KtExpression?,
) {
    if (rawExpression == null) return
    if (rawExpression is KtParenthesizedExpression) return
    val errorReporter = when (val expression = KtPsiUtil.safeDeparenthesize(rawExpression)) {
        is KtIsExpression -> ConfusingWhenBranchReporter.Generic
        is KtBinaryExpression -> ConfusingWhenBranchReporter(expression.operationToken, booleanSubject)
        else -> null
    } ?: return
    val source = KtRealPsiSourceElement(rawExpression)
    errorReporter.report(reporter, source)
}

context(context: CheckerContext, reporter: DiagnosticReporter)
override fun checkPsi(
    element: FirRegularClass,
    source: KtPsiSourceElement,
    psi: KtClassOrObject,
) {
    for (superTypeRef in element.superTypeRefs) {
        val superSource = superTypeRef.source ?: continue
        val parent = superSource.psi?.parent as? KtDelegatedSuperTypeEntry ?: continue
        reporter.reportOn(KtRealPsiSourceElement(parent), FirErrors.IMPLEMENTATION_BY_DELEGATION_IN_EXPECT_CLASS)
    }
}

context(context: CheckerContext, reporter: DiagnosticReporter)
override fun checkPsi(
    element: FirRegularClass,
    source: KtPsiSourceElement,
    psi: KtClass,
) {
    for (superTypeRef in element.superTypeRefs) {
        val superSource = superTypeRef.source ?: continue
        if (superSource.psi?.parent is KtDelegatedSuperTypeEntry) {
            reporter.reportOn(superSource, FirErrors.DELEGATION_IN_INTERFACE)
        }
    }
}

context(context: CheckerContext, reporter: DiagnosticReporter)
override fun checkPsi(
    element: FirNamedFunction,
    source: KtPsiSourceElement,
    psi: KtFunction,
) {
    val typeParamsNode = psi.typeParameterList
    val nameNode = psi.nameIdentifier

    if (typeParamsNode != null && nameNode != null && typeParamsNode.startOffset > nameNode.startOffset) {
        reporter.reportOn(
            source,
            FirErrors.DEPRECATED_TYPE_PARAMETER_SYNTAX
        )
    }
}

context(context: CheckerContext, reporter: DiagnosticReporter)
override fun checkPsi(
    element: FirProperty,
    source: KtPsiSourceElement,
    psi: KtExpression,
) {
    if (psi is KtProperty && psi.typeParameterList != null) {
        reporter.reportOn(source, FirErrors.LOCAL_VARIABLE_WITH_TYPE_PARAMETERS)
    }
}

context(context: CheckerContext, reporter: DiagnosticReporter)
override fun checkPsi(
    element: FirConstructor,
    source: KtPsiSourceElement,
    psi: KtDeclaration,
) {
    if (psi is KtConstructor<*> && psi.modifierList != null && psi.getConstructorKeyword() == null) {
        reporter.reportOn(source, FirErrors.MISSING_CONSTRUCTOR_KEYWORD)
    }
}

context(context: CheckerContext, reporter: DiagnosticReporter)
override fun checkPsi(
    element: FirTypeParameter,
    source: KtPsiSourceElement,
    psi: KtTypeParameter,
) {
    val [constraint, params] = element.bounds.partition { it.psi?.parent is KtTypeConstraint }
    if (params.isNotEmpty() && constraint.isNotEmpty()) {
        reporter.reportOn(source, FirErrors.MISPLACED_TYPE_PARAMETER_CONSTRAINTS)
    }
}

context(context: CheckerContext, reporter: DiagnosticReporter)
override fun checkPsi(
    element: FirFunctionCall,
    source: KtPsiSourceElement,
    psi: PsiElement,
) {
    for (typeProjection in element.typeArguments) {
        val psiTypeArgument = typeProjection.source?.psi as? KtTypeProjection ?: continue
        val typeReference = psiTypeArgument.typeReference ?: continue

        if (!typeReference.isPlaceholder) continue

        for (annotation in typeReference.annotationEntries) {
            reporter.reportOn(
                annotation.toKtPsiSourceElement(), FirErrors.UNSUPPORTED,
                MESSAGE
            )
        }
    }
}
